from runpy import run_path
clamp = run_path('clamp.py')['clamp']
for value, lower, upper in [(0, 2, 1), (-10, -1, -2), (0.0, 0.5, -0.5)]:
    try:
        clamp(value, lower, upper)
    except ValueError:
        continue
    raise AssertionError(('Expected ValueError for reversed bounds', value, lower, upper))
print('Independent reversed-bound cases passed')
